 const ps=[...a.sections[0][1].matchAll(/<p>[\s\S]*?<\/p>/g)].map(m=>m[0]);
 if(!ps[0]?.includes('ReLU(z)')||!ps[1]?.includes('简化FFN'))throw Error('TP opening changed: inspect prose order');
