// mcp-protocol.js
/* Original Chinese lesson; build-mcp-protocol.py embeds source and actual observations. */
const mcpProtocolFiles={"client_lab.py": "\"\"\"Actual official-SDK stdio requests and cancellation, with independent source checks.\n\nPython 3.12 + requirements.txt. Every connection launches its own read-only server.\nModern discovery and legacy initialize are exercised as separate connections.\n\"\"\"\nimport argparse\nfrom importlib.metadata import version\nimport json\nimport os\nfrom pathlib import Path\nimport platform\nimport sys\nimport tempfile\n\nimport anyio\nfrom mcp import MCPError, types\nfrom mcp.client import ClientSession\nfrom mcp.client.stdio import StdioServerParameters, stdio_client\n\n\nROOT = Path(__file__).resolve().parent\n\n\nclass Tap:\n    \"\"\"Observe actual messages on the SDK transport; never synthesize messages.\"\"\"\n    def __init__(self, stream, trace, direction):\n        self.stream, self.trace, self.direction = stream, trace, direction\n\n    @property\n    def last_context(self):\n        return getattr(self.stream, \"last_context\", None)\n\n    def record(self, item):\n        if hasattr(item, \"message\"):\n            self.trace.append({\"direction\": self.direction,\n                               \"message\": item.message.model_dump(by_alias=True, exclude_none=True)})\n\n    async def send(self, item):\n        self.record(item)\n        await self.stream.send(item)\n\n    async def receive(self):\n        item = await self.stream.receive()\n        self.record(item)\n        return item\n\n    def __aiter__(self):\n        return self\n\n    async def __anext__(self):\n        try:\n            return await self.receive()\n        except anyio.EndOfStream:\n            raise StopAsyncIteration\n\n    async def aclose(self):\n        await self.stream.aclose()\n\n    async def __aenter__(self):\n        return self\n\n    async def __aexit__(self, *exc):\n        await self.aclose()\n\n\ndef events(path):\n    return [json.loads(line) for line in path.read_text().splitlines()] if path.exists() else []\n\n\nasync def event_arrives(path, name):\n    with anyio.fail_after(5):\n        while True:\n            found = [row for row in events(path) if row[\"event\"] == name]\n            if found:\n                return found[-1]\n            await anyio.sleep(.01)\n\n\ndef value(result):\n    assert not result.is_error\n    assert json.loads(result.content[0].text) == result.structured_content\n    return result.structured_content\n\n\ndef matches_source(data, source, batch_ids):\n    expected = [number for batch in batch_ids for number in source[\"batches\"][batch]]\n    return (data.get(\"task_id\") == source[\"task_id\"] and data.get(\"version\") == source[\"version\"]\n            and data.get(\"batch_ids\") == batch_ids and data.get(\"values\") == expected\n            and data.get(\"total\") == sum(expected))\n\n\nasync def connection(folder, legacy=False, wrong_total=False):\n    trace, progress = [], []\n    label = \"wrong-total\" if wrong_total else \"legacy\" if legacy else \"modern\"\n    log = folder / (label + \".jsonl\")\n    server = StdioServerParameters(command=sys.executable,\n                                  args=[str(ROOT / \"server.py\"), \"--fixture\", str(ROOT / \"orders.json\"), \"--events\", str(log)])\n    if wrong_total:\n        server.args.append(\"--wrong-total\")\n    with (folder / (label + \".stderr\")).open(\"w\") as stderr:\n        async with stdio_client(server, errlog=stderr) as (read, write):\n            async with ClientSession(Tap(read, trace, \"server_to_client\"), Tap(write, trace, \"client_to_server\"),\n                                     read_timeout_seconds=5, client_info=types.Implementation(name=\"infra-guide-host\", version=\"1.0.0\")) as session:\n                initial = await session.initialize() if legacy else await session.discover()\n                metadata = initial.model_dump(by_alias=True, exclude_none=True)\n                tools = await session.list_tools()\n                advertised = {tool.name: tool.input_schema for tool in tools.tools}\n                assert set(advertised) == {\"read_batch\", \"scan_batches\", \"watch_batch\"}\n                base = value(await session.call_tool(\"read_batch\", {\"task_id\": \"report-A\", \"batch_id\": \"base\"}))\n                assert base[\"total\"] == 37\n                if wrong_total:\n                    wrong = await session.call_tool(\"scan_batches\", {\"task_id\": \"report-A\", \"batch_ids\": [\"base\", \"late\"]})\n                    data = value(wrong)\n                    source = json.loads((ROOT / \"orders.json\").read_text())\n                    expected = sum(sum(v) for v in source[\"batches\"].values())\n                    rejected = not matches_source(data, source, [\"base\", \"late\"])\n                    assert not wrong.is_error and rejected\n                    result = {\"metadata\": metadata, \"scan\": data, \"is_error\": wrong.is_error,\n                              \"independent_expected\": expected, \"semantic_error_rejected\": rejected}\n                elif legacy:\n                    result = {\"metadata\": metadata, \"base\": base}\n                else:\n                    invalid = await session.call_tool(\"read_batch\", {\"task_id\": \"report-A\", \"batch_id\": 27})\n                    missing = await session.call_tool(\"read_batch\", {\"task_id\": \"report-A\", \"batch_id\": \"missing\"})\n                    assert invalid.is_error and missing.is_error\n                    try:\n                        await session.call_tool(\"unknown_tool\", {})\n                    except MCPError as error:\n                        protocol_error = {\"code\": error.code, \"message\": str(error)}\n                    else:\n                        raise AssertionError(\"unknown tool should produce a protocol error\")\n                    progress_ready = anyio.Event()\n\n                    async def on_progress(done, total, message):\n                        progress.append({\"done\": done, \"total\": total, \"message\": message})\n                        if done == 2:\n                            progress_ready.set()\n\n                    scan = value(await session.call_tool(\"scan_batches\", {\"task_id\": \"report-A\", \"batch_ids\": [\"base\", \"late\"]},\n                                                         progress_callback=on_progress))\n                    with anyio.fail_after(5):\n                        await progress_ready.wait()\n                    cancellation_started, cancellation_finished = anyio.Event(), anyio.Event()\n                    pending = {}\n\n                    async def watch_progress(done, total, message):\n                        pending[\"progress\"] = {\"done\": done, \"total\": total, \"message\": message}\n                        cancellation_started.set()\n\n                    async def waiting_call():\n                        try:\n                            with anyio.CancelScope() as scope:\n                                pending[\"scope\"] = scope\n                                try:\n                                    await session.call_tool(\"watch_batch\", {\"task_id\": \"report-A\", \"batch_id\": \"base\"},\n                                                            progress_callback=watch_progress)\n                                except anyio.get_cancelled_exc_class():\n                                    pending[\"cancelled\"] = True\n                                    raise\n                        finally:\n                            cancellation_finished.set()\n\n                    async with anyio.create_task_group() as group:\n                        group.start_soon(waiting_call)\n                        with anyio.fail_after(5):\n                            await cancellation_started.wait()\n                            pending[\"scope\"].cancel()\n                            await cancellation_finished.wait()\n                        cleanup = await event_arrives(log, \"watch_cleanup\")\n                        assert cleanup[\"file_closed\"] and pending[\"cancelled\"]\n                    after_cancel = value(await session.call_tool(\"read_batch\", {\"task_id\": \"report-A\", \"batch_id\": \"late\"}))\n                    result = {\"metadata\": metadata, \"base\": base, \"invalid_is_error\": invalid.is_error,\n                              \"missing_is_error\": missing.is_error, \"protocol_error\": protocol_error,\n                              \"scan\": scan, \"progress\": progress, \"cancel_progress\": pending[\"progress\"],\n                              \"cancelled_waiter\": pending[\"cancelled\"], \"server_cleanup\": cleanup,\n                              \"after_cancel\": after_cancel}\n    rows = events(log)\n    pid = next(row[\"pid\"] for row in rows if row[\"event\"] == \"server_started\")\n    try:\n        os.kill(pid, 0)\n    except ProcessLookupError:\n        reaped = True\n    else:\n        reaped = False\n    assert reaped and rows[-1][\"event\"] == \"server_stopped\"\n    result.update(trace=trace, events=[{k: v for k, v in row.items() if k != \"pid\"} for row in rows],\n                  server_exit_event=True, server_process_reaped=reaped, tools=advertised)\n    return result\n\n\ndef independent_oracle(result):\n    source = json.loads((ROOT / \"orders.json\").read_text())\n    modern, legacy = result[\"modern\"], result[\"legacy\"]\n    expected_values = source[\"batches\"][\"base\"] + source[\"batches\"][\"late\"]\n    assert matches_source(modern[\"scan\"], source, [\"base\", \"late\"])\n    assert sum(expected_values) == 42\n    assert legacy[\"base\"] == modern[\"base\"]\n    outgoing = [row[\"message\"] for row in modern[\"trace\"] if row[\"direction\"] == \"client_to_server\"]\n    incoming = [row[\"message\"] for row in modern[\"trace\"] if row[\"direction\"] == \"server_to_client\"]\n    watch = next(row for row in outgoing if row.get(\"method\") == \"tools/call\" and row[\"params\"][\"name\"] == \"watch_batch\")\n    cancel = next(row for row in outgoing if row.get(\"method\") == \"notifications/cancelled\")\n    assert cancel[\"params\"][\"requestId\"] == watch[\"id\"]\n    assert not any(row.get(\"id\") == watch[\"id\"] for row in incoming)\n    assert modern[\"server_cleanup\"][\"request_id\"] == watch[\"id\"]\n    assert modern[\"after_cancel\"][\"total\"] == sum(source[\"batches\"][\"late\"])\n    assert [row[\"done\"] for row in modern[\"progress\"]] == [1, 2]\n    assert outgoing[0][\"method\"] == \"server/discover\"\n    assert not any(row.get(\"method\") == \"initialize\" for row in outgoing)\n    requests = [row for row in outgoing if \"id\" in row]\n    assert len({row[\"id\"] for row in requests}) == len(requests)\n    for request in requests:\n        metadata = request[\"params\"][\"_meta\"]\n        assert metadata[\"io.modelcontextprotocol/protocolVersion\"] == \"2026-07-28\"\n        assert metadata[\"io.modelcontextprotocol/clientInfo\"][\"name\"] == \"infra-guide-host\"\n        assert \"io.modelcontextprotocol/clientCapabilities\" in metadata\n    legacy_out = [row[\"message\"] for row in legacy[\"trace\"] if row[\"direction\"] == \"client_to_server\"]\n    assert legacy_out[0][\"method\"] == \"initialize\"\n    assert legacy_out[1][\"method\"] == \"notifications/initialized\"\n    assert legacy[\"metadata\"][\"protocolVersion\"] == \"2025-11-25\"\n    assert result[\"wrong_total\"][\"scan\"][\"total\"] == 41\n    assert result[\"wrong_total\"][\"semantic_error_rejected\"] and not result[\"wrong_total\"][\"is_error\"]\n    return {\"expected_total\": 42, \"cancel_request_id\": watch[\"id\"], \"cancelled_response_absent\": True,\n            \"all_modern_requests_carry_metadata\": True,\n            \"modern_first_method\": outgoing[0][\"method\"], \"legacy_first_method\": legacy_out[0][\"method\"]}\n\n\nasync def run(folder):\n    result = {\"sdk\": version(\"mcp\"), \"python\": platform.python_version(),\n              \"modern\": await connection(folder), \"legacy\": await connection(folder, legacy=True),\n              \"wrong_total\": await connection(folder, wrong_total=True)}\n    result[\"independent_oracle\"] = independent_oracle(result)\n    result[\"status\"] = \"passed\"\n    return result\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\"--output-dir\", type=Path)\n    args = parser.parse_args()\n    if args.output_dir:\n        args.output_dir.mkdir(parents=True, exist_ok=False)\n        result = anyio.run(run, args.output_dir)\n    else:\n        with tempfile.TemporaryDirectory(prefix=\"infra-mcp-\") as temporary:\n            result = anyio.run(run, Path(temporary))\n    print(json.dumps(result, ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n", "server.py": "\"\"\"Read-only MCP server: official mcp==2.3.0, real stdio, no model or HTTP.\n\nstdout belongs to the protocol. Evidence is written to an explicit JSONL file.\nThis teaching server trusts its local launcher; it implements no authentication.\n\"\"\"\nimport argparse\nfrom contextlib import asynccontextmanager\nimport json\nimport os\nfrom pathlib import Path\n\nimport anyio\nfrom jsonschema import validate, ValidationError\nfrom mcp import MCPError, types\nfrom mcp.server import Server, ServerRequestContext\nfrom mcp.server.stdio import stdio_server\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\"--fixture\", type=Path, required=True)\n    parser.add_argument(\"--events\", type=Path, required=True)\n    parser.add_argument(\"--wrong-total\", action=\"store_true\", help=\"Intentional semantic error for the independent oracle\")\n    args = parser.parse_args()\n    fixture = json.loads(args.fixture.read_text())\n\n    def event(kind, **body):\n        with args.events.open(\"a\", encoding=\"utf8\") as output:\n            output.write(json.dumps({\"event\": kind, **body}, ensure_ascii=False) + \"\\n\")\n\n    batch_schema = {\"type\": \"object\", \"properties\": {\"task_id\": {\"type\": \"string\"}, \"batch_id\": {\"type\": \"string\"}},\n                    \"required\": [\"task_id\", \"batch_id\"], \"additionalProperties\": False}\n    scan_schema = {\"type\": \"object\", \"properties\": {\"task_id\": {\"type\": \"string\"}, \"batch_ids\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"minItems\": 1}},\n                   \"required\": [\"task_id\", \"batch_ids\"], \"additionalProperties\": False}\n    schemas = {\"read_batch\": batch_schema, \"scan_batches\": scan_schema, \"watch_batch\": batch_schema}\n    descriptions = {\"read_batch\": \"Read one fixed order batch.\", \"scan_batches\": \"Read several batches with progress.\",\n                    \"watch_batch\": \"Open a local source and wait until cancelled; demonstration only.\"}\n    output_schema = {\"type\": \"object\", \"properties\": {\n        \"task_id\": {\"type\": \"string\"}, \"version\": {\"type\": \"integer\"},\n        \"batch_ids\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}},\n        \"values\": {\"type\": \"array\", \"items\": {\"type\": \"integer\"}}, \"total\": {\"type\": \"integer\"}},\n        \"required\": [\"task_id\", \"version\", \"batch_ids\", \"values\", \"total\"], \"additionalProperties\": False}\n\n    def result(data=None, error=None):\n        return types.CallToolResult(content=[types.TextContent(type=\"text\", text=error or json.dumps(data, ensure_ascii=False))],\n                                    structured_content=data, is_error=error is not None)\n\n    @asynccontextmanager\n    async def lifespan(server):\n        event(\"server_started\", pid=os.getpid())\n        try:\n            yield None\n        finally:\n            event(\"server_stopped\")\n\n    async def list_tools(ctx: ServerRequestContext, params):\n        event(\"list_tools\", request_id=ctx.request_id, protocol=ctx.protocol_version)\n        return types.ListToolsResult(tools=[types.Tool(name=name, description=descriptions[name], input_schema=schema,\n                                                      output_schema=output_schema)\n                                           for name, schema in schemas.items()])\n\n    async def call_tool(ctx: ServerRequestContext, params):\n        name, arguments = params.name, params.arguments or {}\n        event(\"call_received\", name=name, request_id=ctx.request_id, protocol=ctx.protocol_version)\n        if name not in schemas:\n            raise MCPError(-32602, \"Unknown tool: \" + name)\n        try:\n            validate(arguments, schemas[name])\n        except ValidationError:\n            event(\"input_rejected\", name=name)\n            return result(error=\"Arguments do not match the advertised JSON Schema\")\n        if arguments[\"task_id\"] != fixture[\"task_id\"]:\n            event(\"business_rejected\", name=name)\n            return result(error=\"The requested task does not exist\")\n        batch_ids = arguments.get(\"batch_ids\", [arguments.get(\"batch_id\")])\n        if any(batch not in fixture[\"batches\"] for batch in batch_ids):\n            event(\"business_rejected\", name=name)\n            return result(error=\"The requested batch does not exist\")\n        if name == \"watch_batch\":\n            try:\n                with args.fixture.open(\"rb\") as resource:\n                    resource.read(1)\n                    event(\"watch_opened\", request_id=ctx.request_id)\n                    try:\n                        await ctx.session.report_progress(1, total=2, message=\"local source opened\")\n                        await anyio.sleep_forever()\n                    except anyio.get_cancelled_exc_class():\n                        event(\"watch_cancelled\", request_id=ctx.request_id)\n                        raise\n            finally:\n                event(\"watch_cleanup\", request_id=ctx.request_id, file_closed=resource.closed)\n        values = []\n        for index, batch in enumerate(batch_ids, 1):\n            values.extend(fixture[\"batches\"][batch])\n            if name == \"scan_batches\":\n                await ctx.session.report_progress(index, total=len(batch_ids), message=\"read \" + batch)\n        event(\"tool_completed\", name=name, request_id=ctx.request_id)\n        return result({\"task_id\": fixture[\"task_id\"], \"version\": fixture[\"version\"],\n                       \"batch_ids\": batch_ids, \"values\": values,\n                       \"total\": sum(values) - int(args.wrong_total and name == \"scan_batches\")})\n\n    server = Server(\"infra-guide-orders\", version=\"1.0.0\", lifespan=lifespan,\n                    on_list_tools=list_tools, on_call_tool=call_tool)\n\n    async def run():\n        async with stdio_server() as streams:\n            await server.run(*streams, server.create_initialization_options())\n\n    anyio.run(run)\n\n\nif __name__ == \"__main__\":\n    main()\n", "orders.json": "{\n  \"task_id\": \"report-A\",\n  \"version\": 3,\n  \"batches\": {\n    \"base\": [10, 27],\n    \"late\": [5]\n  }\n}\n", "requirements.txt": "annotated-types==0.8.0\nanyio==4.16.0\nattrs==26.1.0\ncffi==2.1.1\nclick==8.5.1\ncryptography==50.0.2\nh11==0.16.0\nhttpcore2==2.16.0\nhttpx2==2.16.0\nidna==3.20\njsonschema==4.26.0\njsonschema-specifications==2025.9.1\nmcp==2.3.0\nmcp-types==2.3.0\nopentelemetry-api==1.45.2\npycparser==3.12\npydantic==2.14.3\npydantic_core==2.50.4\nPyJWT==2.15.1\npython-multipart==0.0.33\nreferencing==0.37.0\nrpds-py==2026.9.1\nsse-starlette==3.7.0\nstarlette==1.10.0\ntruststore==0.10.5\ntyping-inspection==0.4.5\ntyping_extensions==4.16.0\nuvicorn==0.54.0\n", "README.md": "# 真正运行一次 MCP：发现、调用、进度和取消\n\n本实验用官方 **mcp 2.3.0**。本次实际环境是 Python 3.12.13、macOS；程序要求\nPOSIX（macOS/Linux），用 `os.kill(pid, 0)` 独立核对服务端进程是否已经被回收。\n依赖版本固定在 `requirements.txt`。无 LLM、API key、远端服务和第三方账号。\n\n解压完整目录后执行：\n\n```sh\npython3.12 -m venv .venv\n.venv/bin/python -m pip install -r requirements.txt\n.venv/bin/python -B client_lab.py > result.json\n```\n\n要保留每个独立服务端的真实事件、标准错误与 PID 观察，可指定一个**尚不存在**的目录：\n\n```sh\n.venv/bin/python -B client_lab.py --output-dir run-01 > result.json\npython3 -m json.tool result.json\n```\n\n`result.json` 是客户端真实运行生成的输出，不是本仓库预制答案。客户端的 `Tap`\n只观察官方 SDK 在 stdio 传输上实际发送和收到的类型化消息；它不伪造响应、请求ID、\n取消或进度。服务端标准输出完全留给协议，事件另写入 JSONL 文件。\n\n## 同一份来源\n\n`orders.json` 的 `report-A/v3` 包含基础批次 `[10,27]` 和补录批次 `[5]`。\n每次调用显式传 `task_id` 与批次名，正确总数为42。服务端只提供这份固定资料；\n此任务字段用于明确业务目标，不是身份认证或访问凭据。\n\n|独立进程|实际做什么|应观察到什么|\n|---|---|---|\n|modern|官方 `ClientSession.discover()`，使用2026-07-28；发现3个工具，实际读、扫描、等待、取消|每个请求带版本/客户端信息/能力；读基础37、扫描42；收到2个进度；取消真实关闭等待所持文件；同一连接仍能读取补录5|\n|legacy|另一进程调用 `ClientSession.initialize()`，明确使用2025-11-25|`initialize → response → notifications/initialized → tools/list`；不把旧握手拼入现代连接|\n|wrong-total|第三进程开启 `--wrong-total`，真正返回结构合法的错误总数41|SDK的输出结构校验通过，`isError=false`，但直接读取权威来源的独立判据拒绝|\n\n2026-07-28版没有初始化握手。`server/discover` 是可选探测，双代 stdio 客户端可以\n用它判断兼容路径；它不是每次调用前的必需动作。此实验选择主动探测以留下可检查证据。\n\n## 失败分层\n\n参数 `batch_id=27` 不符合声明的字符串类型；服务端自己的 JSON Schema 校验返回\n`isError=true`。`batch_id=\"missing\"` 类型正确，但业务资料不存在，也返回工具错误。\n未知工具名则返回 JSON-RPC 错误 `-32602`，由客户端 `MCPError` 捕获。\n\n这些失败不是同一种状态。`resultType=\"complete\"` 表明本轮协议结果已经返回，不证明\n工具业务成功；`isError=false` 和结构合法也不证明总数正确。独立判据重新读取\n`orders.json`，核对来源版本、值和总数。\n\n## 进度、取消与退出\n\n正常扫描实际发出 `1/2`、`2/2` 两份进度通知，客户端等待回调到齐；真实传输中回调\n可能晚于工具最终响应处理，不能仅凭 `call_tool()` 返回便断言回调已跑完。\n\n`watch_batch` 真实打开一个来源文件，报告一次进度后等待。客户端等到这份进度后，\n取消等待该调用的 AnyIO 取消作用域。SDK 2.3.0 真正发出 `notifications/cancelled`，\n服务端处理器收到取消，`finally` 关闭文件。程序从独立事件文件核对 `file_closed=true`，\n再确认同一连接仍然可读补录5；不是把杀死整个服务端冒充单请求取消。\n\n最后退出 stdio 上下文，SDK关闭输入端，服务端收到EOF、退出，客户端独立核对进程\n已经被回收。实验服务端没有创建孙进程；不据此推断 SDK 会清理任意服务端派生进程。\n\n协议取消要求协作。它不撤销已经提交的外部业务效果，也不证明任意工具都能立即停止。\n\n## 文件与验证边界\n\n- `server.py`：真正的官方 SDK stdio 服务端；本地只读工具和取消资源清理。\n- `client_lab.py`：真正的 `ClientSession`、新服务端子进程、传输观测及独立来源验收。\n- `orders.json`：受控的权威输入。\n- `requirements.txt`：本次安装的精确依赖版本。\n- `validation.json`：源码摘要与本次实际输出；不能替代自己的重跑。\n\n本实验没有实现HTTP/Streamable HTTP、OAuth、远端工具、模型选择、写入幂等、业务回滚\n或Kairo适配器。`clientInfo` 是客户端自行声明的实现信息；同一个连接和相同\n`task_id` 都不代替可信身份或业务授权。\n"};
const mcpProtocolEvidence={"sdk": "2.3.0", "python": "3.12.13", "modern_metadata": {"_meta": {"io.modelcontextprotocol/serverInfo": {"name": "infra-guide-orders", "version": "1.0.0"}}, "ttlMs": 0, "cacheScope": "private", "supportedVersions": ["2026-07-28"], "capabilities": {"tools": {"listChanged": false}}, "resultType": "complete"}, "legacy_metadata": {"protocolVersion": "2025-11-25", "capabilities": {"tools": {"listChanged": false}}, "serverInfo": {"name": "infra-guide-orders", "version": "1.0.0"}}, "call_request": {"jsonrpc": "2.0", "id": 3, "method": "tools/call", "params": {"name": "read_batch", "arguments": {"task_id": "report-A", "batch_id": "base"}, "_meta": {"io.modelcontextprotocol/protocolVersion": "2026-07-28", "io.modelcontextprotocol/clientInfo": {"name": "infra-guide-host", "version": "1.0.0"}, "io.modelcontextprotocol/clientCapabilities": {}}}}, "call_response": {"jsonrpc": "2.0", "id": 3, "result": {"content": [{"text": "{\"task_id\": \"report-A\", \"version\": 3, \"batch_ids\": [\"base\"], \"values\": [10, 27], \"total\": 37}", "type": "text"}], "isError": false, "resultType": "complete", "structuredContent": {"task_id": "report-A", "version": 3, "batch_ids": ["base"], "values": [10, 27], "total": 37}, "_meta": {"io.modelcontextprotocol/serverInfo": {"name": "infra-guide-orders", "version": "1.0.0"}}}}, "protocol_error_response": {"jsonrpc": "2.0", "id": 6, "error": {"code": -32602, "message": "Unknown tool: unknown_tool"}}, "cancel_notification": {"jsonrpc": "2.0", "method": "notifications/cancelled", "params": {"requestId": 8, "reason": "caller cancelled"}}, "source_sha256": {"client_lab.py": "48cd164d01d0dd16f0f174e5cb0ffd2b1b3f70cbfe0850c4de29440331820dbe", "server.py": "7bc7dfeb50b6af28696c509b5ee02bfc4935fc4825d16fbc696fcb93018a76e5", "orders.json": "a67bf68f5507399832fcce6ca683f4dd085a174d51dcece7b0455c85aee6ca73", "requirements.txt": "bb7f562f555c5b4f170d22c2871a57ab1dd33d34466c32c3c90d563ef38704da", "README.md": "05be3f5dbbef2b10eba76e73f6a183f9e6aa33f340a56902142c541ceef95f62"}, "read_batch_contract": {"name": "read_batch", "inputSchema": {"type": "object", "properties": {"task_id": {"type": "string"}, "batch_id": {"type": "string"}}, "required": ["task_id", "batch_id"], "additionalProperties": false}}, "normal_sdk_excerpt": {"fragments": [{"file": "client_lab.py", "start_line": 104, "end_line": 104, "method": "server/discover", "expression": "await session.discover()"}, {"file": "client_lab.py", "start_line": 106, "end_line": 106, "method": "tools/list", "expression": "await session.list_tools()"}, {"file": "client_lab.py", "start_line": 109, "end_line": 109, "method": "tools/call", "expression": "await session.call_tool(\"read_batch\", {\"task_id\": \"report-A\", \"batch_id\": \"base\"})"}], "text": "await session.discover()\nawait session.list_tools()\nawait session.call_tool(\"read_batch\", {\"task_id\": \"report-A\", \"batch_id\": \"base\"})"}};
