// progressive-training-reading.js
/* Follow one update from supervision to state lifetime; keep published evidence intact. */
(()=>{
 const p=(...items)=>items.map(x=>'<p>'+x+'</p>').join('');
 const table=(headers,rows)=>'<div class="table-wrap"><table><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
 const formula=(title,body,note)=>'<div class="knowledge-formula"><small>'+title+'</small><div>'+body+'</div>'+(note?'<p>'+note+'</p>':'')+'</div>';
 const link=(id,label)=>'<a class="inline-link" href="#/article/'+id+'">'+label+' →</a>';
 const figures=html=>html.match(/<figure\b[\s\S]*?<\/figure>/g)||[];
 const codes=html=>html.match(/<div class="code-block">[\s\S]*?<\/pre><\/div>/g)||[];
 const details=html=>html.match(/<details\b[\s\S]*?<\/details>/g)||[];
 const sectionSubjects={'subsection-1-40kyla':'逻辑载荷、存储共享与设备读数','subsection-3-1xxxqsz':'58参数模型的状态分配','subsection-8-1hcmeye':'重计算的保存量与执行次数','subsection-9-1sk5pf9':'预取缓冲与存活时间','subsection-9-r44dc9':'量化对象与权重展开','subsection-11-em7gfe':'张量与优化器状态实战','subsection-11-11crht8':'反向保存量与重计算实战','subsection-5-o0j3lt':'不等长微批的权重与梯度'};
 const heading=(html,id,index=0)=>{const text=(html.match(/<h3\b[^>]*>[\s\S]*?<\/h3>/g)||[])[index];if(!text)throw Error('Missing training heading: '+id);const anchored=text.replace('<h3>','<h3 id="'+id+'">');return sectionSubjects[id]?anchored.replace(/>[\s\S]*<\/h3>$/, '>'+sectionSubjects[id]+'</h3>'):anchored;};
 const fold=(label,body)=>'<details class="full-code"><summary>'+label+'</summary>'+body+'</details>';
 const select=(id,count)=>{const a=articles.find(a=>a.id===id);if(!a||a.sections.length!==count)throw Error('Training reading section count: '+id);return a;};
 // Keep every published destination, including source citations and individual downloads.
 const retainLinks=(before,after)=>{
  const counts=new Map();for(const m of after.matchAll(/\bhref="([^"]+)"/g))counts.set(m[1],(counts.get(m[1])||0)+1);
  const missing=[];for(const m of before.matchAll(/<a\b[^>]*href="([^"]+)"[^>]*>[\s\S]*?<\/a>/g)){const n=counts.get(m[1])||0;if(n)counts.set(m[1],n-1);else missing.push(m[0]);}
  return after+(missing.length?'<p class="practice-links">'+missing.join(' · ')+'</p>':'');
 };
 const replace=(a,bodies)=>{
  if(a.sections.length!==bodies.length)throw Error('Training reading body count: '+a.id);
  const before=a.sections.map(s=>s[1]);
  const after=bodies.map((body,i)=>retainLinks(before[i],body));
  const pres=html=>html.match(/<pre\b[\s\S]*?<\/pre>/g)||[];
  if(JSON.stringify(pres(before.join('')))!==JSON.stringify(pres(after.join(''))))throw Error('Training reading changed source: '+a.id);
  if(JSON.stringify(figures(before.join('')).sort())!==JSON.stringify(figures(after.join('')).sort()))throw Error('Training reading changed figures: '+a.id);
  a.sections.forEach((s,i)=>{s[1]=after[i];});a.updated='2026.11.08';
  const summaries={'autograd-training':'用同一个小模型走完预测、损失、梯度和一次更新，再对照整批与微批的结果。','gpu-memory':'先数清训练保存的对象，再按精度和存活时间推导内存，最后比较累积、重算和分片。'};
  a.desc=summaries[a.id];a.intro=a.desc;
 };

 const training=select('autograd-training',10),t=training.sections.map(s=>s[1]);
 replace(training,[
  p('训练把模型的候选得分与已知目标比较，再用比较结果调整参数。本章继续使用前两章的TinyDecoder：词表V=8、隐藏宽D=8、批大小B=2、输入长T=4、两个注意力头、前馈中间宽F=12，共664个独立参数元素。它采用可学习绝对位置表；位置章的手工RoPE向量不参与这次训练。',
  '先区分四个对象：输入ID决定查哪条词向量；标签给出该位置应预测的下一词元；logits是模型给8个候选的原始分数；损失loss是这些分数与标签比较后得到的一个数。参数是被调整的对象，标签提供目标。这里的0是普通词元，−100才是交叉熵约定的忽略标签，且−100只放在标签里。',
  '两条原始序列各有5项。输入取前4项，目标取后4项，所以位置t根据截至t的前缀预测原序列t+1项。代码在进入模型前完成移位，forward只返回logits。为演示监督计数，再将第一行后3项、第二行最后1项标签改为−100。')+
  table(['原始序列','输入ID，位置0…3','移位后的完整目标','参与本次损失的标签'],[
   ['[0,1,2,3,4]','[0,1,2,3]','[1,2,3,4]','[1,−100,−100,−100]'],
   ['[4,5,6,7,0]','[4,5,6,7]','[5,6,7,0]','[5,6,7,−100]']
  ])+
  p('有效监督位置是标签不为−100的位置，本例两行分别有1、3项，合计N=4。本章目标是让这4项等权：先求每项损失，再相加除以4。忽略标签只决定哪项进入损失，attention的因果掩码仍决定哪个输入可被读取；一般而言，一个没有直接监督的位置仍可能通过后续有效位置收到梯度。',
  '先固定这个目标，后面才比较整批和微批。若任务要求每条序列等权，也可以先求各序列均值再平均，但那会给这里两行不同的每词元权重，需要另写目标。换用会在内部移位的封装模型时，也要按它的接口重新交付标签。')+
  link('transformer-block','回看同一模型的结构与664参数账本'),

  p('交叉熵（cross entropy）把正确类别的概率转成损失。对单个有效位置，设有V个候选，zⱼ是第j项logit，y是正确编号；Softmax把整行分数转换为概率pⱼ。下面先用一个独立二分类算例，V=2、z=[ln2,0]、y=0，不把它当成八类Decoder的实际输出。')+
  formula('由候选分数得到一项损失','pⱼ = exp(zⱼ) / Σₖexp(zₖ)<br>ℓ = −ln pᵧ = ln(Σₖexp(zₖ))−zᵧ','j、k遍历同一位置的词表候选；ln是自然对数。正确目标概率越大，这项损失越小。')+
  p('本例指数为[2,1]，概率为[2/3,1/3]，损失为ln(3/2)≈0.405465。保持分数只把目标换成第1项，损失变成ln3≈1.098612。即使正确项已经分数最高，只要概率还小于1，损失仍会推动概率继续变化。',
  '梯度描述损失随某个数变化的速率。对zⱼ求导，log-sum-exp一项给exp(zⱼ)/Σₖexp(zₖ)=pⱼ；减去zᵧ一项只在j=y时贡献−1。记1[j=y]为“成立取1，否则取0”，便得到以下结果。')+
  formula('交叉熵对logits的局部梯度','∂ℓ/∂zⱼ = pⱼ−1[j=y]<br>本例：[2/3−1,1/3−0] = [−1/3,+1/3]','若暂把两个logit当作自由参数，沿负梯度更新会提高正确项、降低另一项。真实模型还要将这份导数传给生成分数的参数。')+
  p('恢复本章的4项平均目标时，每个有效位置的这份导数还要除以4；忽略位置对自己的logits贡献为0。计算中用稳定的log-sum-exp或先减整行最大分数，可避免直接exp(1000)溢出。源码将原始logits交给cross_entropy，由它完成相应计算；先Softmax再传入会改变输入含义。'),

  p('计算图记录本次前向中“哪个结果由哪些输入算出”。反向传播从损失开始，沿依赖反向计算局部变化率；链式法则把相连两步的变化率相乘，同一输入被多处使用时，再把各路径贡献相加。自动求导负责组织这项计算，不替我们定义正确标签或损失分母。',
  '另用一个独立标量算例走完整条链：参数w=2，输入x=3，目标y=5，预测u=wx，损失L=(u−y)²/2。前向依次得到u=6、u−y=1、L=0.5。反向先有∂L/∂u=u−y=1，再有∂u/∂w=x=3，所以∂L/∂w=1×3=3。')+
  formula('由梯度完成一次SGD更新','w新 = w旧−η·∂L/∂w<br>η=0.1：w新=2−0.1×3=1.7','SGD是随机梯度下降，η是学习率。本例更新后预测为5.1、损失为0.005；这是这组数的计算结果。')+
  p('回到Decoder，损失先对logits求导，再经过输出归一化、Block和输入查表返回参数。共享词表E既用于输入查表，又用于输出打分，因此∂L/∂E等于两条路径贡献之和。残差加法也把梯度送向直接路径和分支。存成两份数值相同的独立矩阵，会分别得到梯度和更新，不再是同一个共享参数。')+
  table(['操作','改变什么','本章调用时机'],[
   ['forward / loss_sum','创建本次前向结果与求导依赖','每个微批一次'],
   ['backward()','把本次贡献累加到参数.grad','每个微批一次，权重此时保持'],
   ['optimizer.step()','按梯度及优化器规则调整参数','整个窗口最后一次'],
   ['zero_grad(set_to_none=True)','让参数不再持有上一窗口的梯度张量','本次窗口开始']
  ])+
  p('叶参数是直接创建、由优化器管理的可学习张量，.grad保存累计导数。源码用subtotal继续反向，用subtotal.detach().item()记录普通数字；日志值已脱离求导路径。清梯度、求梯度和应用更新是三个独立动作。'),

  p('现在把求导链恢复成实际形状。B、T、D分别为样本、位置、特征轴；词表轴V决定每个位置有多少候选。整数ID和标签不求导，连续参数与由它们生成的浮点结果参与求导。下面按一次正常前向到更新的顺序列出对象。')+
  table(['节点','本例形状或数量','在训练链上的作用'],[
   ['输入ID / 标签','均为[2,4]，有效标签1+3项','查表 / 选择交叉熵目标'],
   ['词表E / 位置表A','[8,8] / [4,8]','相加形成[2,4,8]初始表示'],
   ['Q、K、V','各[2,2,4,4]','两头分别读取因果前缀'],
   ['注意力输出与两次残差','均回到[2,4,8]','将上下文与前馈修正加入主路径'],
   ['SwiGLU中间量','gate、up及门控乘积为[2,4,12]','经down投影回8维'],
   ['logits → 交叉熵','[2,4,8]→[8,8]，标签[2,4]→[8]','只合并B、T，保留最后的8类'],
   ['参数 / 梯度','664个参数元素；梯度按参数形状保存','共享E只登记一次，接收两条路径'],
   ['SGD更新','η=0.05，momentum=0，不加入历史更新方向','读累计梯度，只调用一次step']
  ])+
  p('前向会保存反向所需的部分输入和中间量，称为供反向使用的激活；具体保存哪些由算子实现决定。每个微批反向后，在默认不保留计算图的条件下，这些保存量可被释放，累计梯度继续留给下一微批。参数则跨越整个更新窗口存活。源码最后不再清梯度，因为main还要逐项比较两条路径的.grad。',
  '模型采用CPU、float64、单线程、随机种子7和零dropout，便于比较很小的舍入差异。664个双精度参数的逻辑载荷为664×8=5312字节；若664项梯度全部建立，再增加5312字节。这个推导未计激活、临时区、Python对象或算子开销，不能作为进程内存。显存章会按对象寿命继续展开。')+
  link('gpu-memory','继续按状态与寿命计算训练内存'),

  p('微批是一次forward/backward处理的输入片段；更新窗口是从清梯度到一次step之间的全部片段。这里整批一次处理两行，微批路径每次处理一行，两个路径都要优化同一组4个有效目标，并且整个窗口内保持初始参数不变。设S₀、S₁为两行有效损失之和，目标及其梯度为：')+
  formula('先固定全窗口分母，再分批求导','L = (S₀+S₁)/4<br>∇L = ∇(S₀/4)+∇(S₁/4)','所以每个微批对自己的损失之和除以同一个4后反向，.grad中的相加就得到整批梯度。')+
  p('另设独立标量算例检查权重：每项损失为(w−y)²/2，初始w=1，第一微批目标[0]、第二微批目标[3,3,3]。第一批总损失0.5、总梯度1，第二批总损失6、总梯度−6。四项等权后L=6.5/4=1.625，梯度−5/4=−1.25。若平均两批的局部均值，则L=(0.5+2)/2=1.25，梯度=(1−2)/2=−0.5。')+
  figures(t[4]).join('')+
  heading(t[4],'subsection-5-o0j3lt')+
  table(['标量算例路径，学习率0.1','损失','累计梯度','一次SGD后的w'],[
   ['四项一起平均','1.625','−1.25','1.125'],
   ['分别对S₀/4、S₁/4反向，再step','1.625','−1.25','1.125'],
   ['两个局部均值等权平均','1.25','−0.5','1.05']
  ])+
  p('supervision_gradients.py末尾实际复核了这三路。它前半段用E[id]/2和六项监督拆解共享表梯度，是词元章的另一份二维夹具；本节只借用末尾的单参数算例，不将其向量或六项标签混入664参数Decoder。',
  '逐微批step会让后续前向读到新参数，因此不再是上面同一函数在同一初值处的梯度和。全窗口N=0时则没有平均目标；TinyDecoder代码先计数，直接返回None，既不forward也不step。分布式时还要统一全局计数和通信参与，本节单进程公式没有DDP平均因子。')+
  link('tokenization-embedding','查看共享词表、六项监督与完整实验源码'),

  p('下面读完整程序时，先按已经走通的依赖定位函数：TinyDecoder.forward负责“输入→logits”，loss_sum负责“logits与标签→有效损失之和”，update负责“窗口归一化→累计梯度→一次SGD”，main负责构造数据并比较两条执行路径。完整源码在折叠区，下载文件与其中代码一致。')+
  table(['函数或语句','对应本章概念','阅读时核对的数'],[
   ['rows[:, :-1] / rows[:, 1:]','输入与目标错开一项','输入[2,4]，有效计数[1,3]'],
   ['F.linear(..., self.token.weight)','共享词表头','仍为664个参数元素'],
   ['reduction="sum" / valid','先求和，再用窗口分母','所有微批都除以4'],
   ['subtotal.backward / optimizer.step','多次求导，最后一次更新','micro_size=1时两次反向、一次step'],
   ['copy.deepcopy(base)','两路从完全相同参数出发','整批micro_size=2，微批micro_size=1']
  ])+
  p('update每次调用都会新建一个无momentum的SGD，再清梯度；本脚本分别在独立模型上完成一次更新。它没有演示跨很多窗口保留Adam或动量状态的训练循环。valid=0的路径已经创建优化器并清梯度，但会在任何forward和step前返回。',
  '正常结果需要同时满足：整批与微批损失相同，逐参数梯度相同，更新后参数相同，并且至少一份参数确实变化。另以参数账本、修改最后输入后的因果前缀不变、全忽略目标不更新作独立检查。程序选择无dropout和逐位置归一化，使拆批不改变模型函数；切换随机机制或批统计后要重新定义可比条件。')+
  details(t[5])[0],

  p('一次更新可以从三个层次验收：数据层确认输入、标签与有效数量；计算层确认logits、损失及梯度；状态层确认优化器确实把更新应用到预期参数。按这个顺序，比较对象的含义先一致，数值差异才有明确解释。',
  '先列每个有效位置的未归约损失，再核对求和与分母。若整批和微批的loss相同，继续逐参数比较.grad，最后比较step后的参数。对同一个初值，普通无momentum SGD满足Δθ=−ηg，可以把实际参数差与这一关系再对照；损失偶然下降不代替这些检查。',
  '出现差异时，从最早偏离的节点向前查。logits不同，查输入、位置、掩码、归一化与随机条件；logits相同而loss不同，查标签、词表轴和分母；loss相同而某个梯度缺失，查detach或参数共享；梯度相同而更新不同，查学习率、优化器状态及参数归属。',
  '因果检查中只改最后输入，前面三个位置应保持。还要另看可见输入变化能否影响对应输出，避免常数模型也通过“不受未来影响”的检查。加入dropout后，拆批可能改变随机数使用顺序；不同内核和浮点归约也可能带来小误差，应结合配置选择容差。'),

  p('数值差分通过重新计算损失近似导数，不使用自动求导图。固定输入及其余参数，只把一个标量z分别改成z+h、z−h，分别求两次损失。中心差分取左右变化的平均斜率，可以给前面的解析导数提供另一条参照。')+
  formula('中心差分','∂L/∂z ≈ [L(z+h)−L(z−h)]/(2h)','两次求值之间保持同一输入、参数、随机条件和损失分母，不执行优化器更新。')+
  p('用独立二分类算例[ln2,0]、y=0检查第一项，应接近−1/3；检查第二项应接近+1/3。步长h太大，弯曲函数的近似偏差较大；太小，两次相近浮点数相减会损失有效数字。可以用float64比较几种h的结果，例如从10⁻³逐步到10⁻⁶，观察是否在一段范围内接近解析值。',
  '扩展到Decoder时，选择共享token表或前馈矩阵中的一项，固定同一批数据，比较差分与该项.grad。共享表的扰动会同时改变输入查表和输出打分，自动求导也必须包含这两条路径。这里给出检查方法；当前tiny_decoder.py执行记录只包含整批/微批对照，未额外记录完整Decoder的逐参数差分。',
  '每查一项都要额外求两次损失，故数值差分适合小模型和少量坐标。涉及离散选择或恰好落在分段边界时，还需说明被比较的导数定义。'),

  p('单机训练先确定“本次更新优化哪个目标”，分布式训练再把同一目标拆到多个进程。rank是进程在通信组内的编号，数据并行让各rank持有同一模型、处理不同数据，并通过梯度归约形成共同更新。它增加了数据划分和通信步骤，目标本身仍要明确。',
  '若R个rank的默认DDP对梯度取平均，全局有效目标数为N，每个rank的损失之和为Sᵣ，那么让本地反向使用R·Sᵣ/N，归约后得到(1/R)Σᵣ∇(R·Sᵣ/N)=∇(ΣᵣSᵣ/N)。这个因子来自所选通信语义；自定义通信或其他归约方式需要重新推导。')+
  table(['带到下一章的记录','本章已固定的内容'],[
   ['数据与目标','两条5项原序列，主动移位，−100忽略，有效数1+3'],
   ['模型与数值条件','664参数、float64、CPU、seed=7、单线程、dropout=0'],
   ['更新边界','全部有效目标等权，η=0.05，窗口末一次SGD'],
   ['数值参照','整批loss、逐参数grad、更新后参数及独立因果检查']
  ])+
  p('后续两进程实验可以用单进程同目标结果作参照，再分别改变设备、通信后端和计算精度。质量比较要先对齐有效监督与更新次数，性能比较再记录同口径有效token吞吐、每步时间及逐rank资源；本章CPU单步记录不提供GPU或NCCL性能结论。')+
  link('gpu-cluster','进入A2.1：把训练进展映射到集群')+
  link('distributed-training','继续检验两个rank的更新语义'),

  p('在匹配平台、已经安装PyTorch 2.5.1的Python环境执行下载的tiny_decoder.py，即可复核本章断言。先预测4项平均和两条路径的关系，再看保留的运行输出。输出中的loss_before是更新前同一目标，loss_after用更新后模型重新计算。')+
  table(['保留记录中的字段','数值与含义'],[
   ['parameters / valid_targets','664 / [1,3]'],
   ['loss_before → loss_after','8.627936874049762 → 7.615537072678819'],
   ['max_grad_diff','3.3306690738754696×10⁻¹⁶，整批与微批的最大逐项梯度差'],
   ['device / torch','cpu / 2.5.1']
  ])+
  p('这些数来自已有CPU执行记录，本次改写没有新增设备运行。两路loss的断言容差为10⁻¹²，梯度和更新后参数使用绝对、相对容差10⁻¹⁰。这里一次更新使训练目标下降；跨更多数据、加入随机性或改变学习率后，要继续观察整体训练与独立评估。')+
  details(t[9])[0]
 ]);

 const memory=select('gpu-memory',11),m=memory.sections.map(s=>s[1]);
 replace(memory,[
  '<div class="mechanism-core" id="memory-state-objects">'+heading(m[0],'subsection-1-40kyla')+
  p('训练内存保存两类东西：跨更新保留的模型状态，以及为当前计算暂存的数据。参数决定模型函数；梯度保存当前窗口的累计导数；优化器状态保存更新规则所需的历史；激活是前向产生、供后续计算或反向使用的中间结果；工作区是算子执行时的临时存储。它们的数量、精度与存活时间一起决定容量。',
  '先接回664参数TinyDecoder：源码把参数转为float64，每元素8字节，参数逻辑载荷为5312字节；全部梯度建立后再增加5312字节。无momentum SGD不为每项参数维护Adam式历史张量。这个账只按源码推导参数和梯度，不计激活与运行时开销。下文会另设58参数AdamW实验和大模型容量题，并逐一标明。',
  '张量的shape给元素数，dtype给每元素字节数：FP32为4，FP16、BF16为2。P表示参数元素总数。numel×element_size得到张量的逻辑载荷；多个张量也可能指向同一底层存储，例如view只改变看待数据的形状或范围。')+
  table(['统计层次','具体含义','与下一层的关系'],[
   ['张量逻辑载荷','元素数×每元素字节数','共享view可能重复计数'],
   ['唯一底层存储载荷','对仍被持有的存储去重求和','还不包含分配器管理与全部运行开销'],
   ['CUDA allocated','PyTorch分配器记录的当前张量分配','是reserved的一部分'],
   ['CUDA reserved','PyTorch分配器向设备保留的内存','还可能保留已无活张量使用的缓存'],
   ['设备级读数 / CPU RSS','设备工具或操作系统各自观察的用量','按工具范围解释，不能与上述数直接相加']
  ])+
  p('独立view实验用8个FP32元素，共32字节。base[:6]与base[2:]各看6项，逻辑相加是48字节，却共享同一块32字节存储；任一view仍被持有，都可能让这整块存储继续存活。下面先数对象，再把同时存活的对象放回时间线上。')+'</div>',

  p('优化器用梯度决定参数怎样变化。SGD直接沿梯度更新；Adam还为每个参数保留两份历史统计：一阶矩m是梯度的指数移动平均，二阶矩v是梯度平方的指数移动平均。它们帮助平滑方向并按历史幅度调整步长；m、v需要跨窗口保存，不能在每次step前重新创建。AdamW还把权重衰减单独施加到参数。',
  '再看一份明确指定的混合精度账本：P=2³⁰=1,073,741,824，每张卡保存完整副本，无卸载。BF16模型权重用于计算，梯度也是BF16；优化器在另一份FP32主权重上更新，再转换回模型权重；m、v各用FP32。主权重是这套策略额外保留的高精度参数副本，不是所有autocast训练都会自动创建的对象。')+
  table(['已分配的状态','每参数字节','总字节','GiB'],[
   ['BF16模型权重','2','2,147,483,648','2'],
   ['BF16梯度','2','2,147,483,648','2'],
   ['FP32更新主副本','4','4,294,967,296','4'],
   ['FP32一阶矩m','4','4,294,967,296','4'],
   ['FP32二阶矩v','4','4,294,967,296','4'],
   ['合计','16','17,179,869,184','16']
  ])+
  p('每项字节数相加得到16P。这里1GiB=2³⁰字节，所以总数正好16GiB，十进制约17.18GB。该表只在五类对象都已经建立并保留时成立，未计激活、标量计数、转换临时量与通信缓冲。',
  '下面旧图使用另一份简化配置：10亿个参数，FP32权重、FP32梯度和两份FP32矩，没有独立主副本，也得到16P字节，约16GB。总倍数相同，组成和P都不同。看见“16P”时，要连同对象清单一起读。')+
  figures(m[1]).join(''),

  heading(m[2],'subsection-3-1xxxqsz')+
  p('用实际运行对象检验上一节的计数方法。tensor_state_bytes.py另建Linear(4,8)→ReLU→Linear(8,2)网络：第一层4×8+8=40项，第二层8×2+2=18项，合计58个参数元素，分在两份权重和两份偏置共4个张量中。它采用PyTorch 2.5.1的AdamW、foreach=False，运行在CPU，和664参数Decoder是两份独立模型。',
  'FP32参数占58×4=232字节。第一次backward生成同尺寸梯度，再加232字节；第一次step才为有梯度的参数建立exp_avg、exp_avg_sq及step计数。两份矩共464字节，4个FP32计数共16字节，所以step后仍持有梯度时为232+232+464+16=944字节。')+
  table(['观察时刻','FP32参数；或FP32参数加BF16 autocast','直接BF16参数','对象变化'],[
   ['创建后','232B','116B','只有参数进入这份状态清单'],
   ['首次backward后','464B','232B','增加梯度，Adam状态仍空'],
   ['首次step后','944B','480B','增加两份矩和4个step标量'],
   ['zero_grad(set_to_none=True)后','712B','364B','参数不再持有梯度张量'],
   ['再次step后，清梯度前','944B','480B','梯度重新建立，状态尺寸保持']
  ])+
  figures(m[2]).join('')+
  p('autocast意为按算子策略自动选择计算精度。这里FP32参数配CPU BF16 autocast，前向输出是BF16，参数、梯度和两份矩仍为FP32，因此保留状态仍是944字节。直接将参数改为BF16时，本实现的梯度与矩也为BF16：4×58×2+16=480字节，没有新增FP32主副本。两种方式改变的对象不同。',
  '这张表数的是参数、梯度、矩与计数张量，不是CPU进程用量或整步峰值。step创建状态期间还可能出现临时量。若改用保留梯度并把数值清零，梯度存储仍在，不能套用712字节；解除引用后，分配器也可能继续缓存内存。完整源码与各阶段输出保留在最后的实战区。'),

  p('梯度累积把一个更新窗口拆成多次前向和反向：每次微批产生自己的计算图，反向后释放该批所需保存量，把梯度加到同一组.grad，窗口末更新一次。这样可以减少同时处理的激活，而模型参数与优化器历史仍须保留。',
  '数据并行让多个训练进程各持模型副本、处理不同数据；rank是进程在通信组内的编号。设R个rank，每rank每微批b条样本，累积a次；若各rank样本数一致且窗口完整，总样本数为Rba。这个式子只数输入，不自动证明损失等价。均值损失的分母、随机条件和更新边界还要与目标一致。')+
  formula('等大微批的有效batch','B有效 = B微批 × 累积次数 × rank数','例如4个rank、每rank每微批8条、累积4次，共4×8×4=128条。')+
  p('改为每rank4条、累积8次，仍处理128条；每次即时反向时，单批激活通常减少，已建立的参数、梯度、Adam状态大小不因累积次数翻倍。若先做8次前向、把带图loss都留到最后才统一反向，这些图也会同时存活，无法取得相同的激活收益。',
  '沿用前节P=2³⁰的五缓冲题，微批变小后五类状态仍为16GiB。变长文本则要同时记录实际输入形状与有效监督数：padding位置可能不进loss，仍可能占计算与激活存储；不同微批的有效token数也可能不同，应沿全窗口目标归一化。')+
  link('distributed-training','回看A2.2的有效token归一化反例'),

  p('浮点格式用符号、指数和尾数表示数值：指数位影响可表示范围，尾数位影响同一数量级内的间隔。FP16和BF16都占2字节；FP16的指数范围较窄，BF16的指数范围更接近FP32、尾数则较短。计算精度降低可能影响舍入与稳定性，需要结合模型和硬件验证。',
  'FP16训练常用损失缩放：先把损失乘缩放因子s，反向得到s倍梯度，再在更新前除以s。链式法则保证理想算术下恢复原梯度；放大发生在小梯度被低精度舍入之前，才有机会保留信号。它不等于提高所有运算的精度。',
  '独立看一次转换：假设FP16支持渐进下溢并按最近值舍入，最小正次正规数为2⁻²⁴。2⁻²⁷直接转为FP16会成为0；先乘2⁸得到可表示的2⁻¹⁹，再在FP32中除以2⁸，可还原2⁻²⁷。已变成0后再放大，仍是0。实际训练有多条算子和存储路径，这里只解释一处转换。',
  'BF16通常无需这种FP16式的GradScaler，但仍需检查有限值和训练质量。autocast只选择算子的计算策略，是否保留BF16参数、FP32主权重及哪种梯度，要从实际对象读取。若在五缓冲题中只把梯度从2字节改成4字节，其他对象不变，状态就由16P增为18P，即18GiB。'),

  p('下面是独立的CUDA FP16累积片段，用来说明窗口内各动作的先后。model假定为已经设置好的DDP模型，accum为累积次数，criterion返回均值损失；各微批的有效分母相同，完整窗口才能用loss/accum。它不直接执行前面的CPU状态实验，也不代表五缓冲账本。',
  '正常顺序为：窗口开始清梯度；各微批用同一缩放因子前向并反向；最后一次反向完成后，撤销一次缩放，按需裁剪，再尝试优化器更新；随后调整下一窗口的缩放因子并清梯度。前几个微批用no_sync延后DDP同步，作用域需同时包住forward和backward。')+
  codes(m[5])[0]+
  p('scaler.step(optimizer)会在需要时先撤销缩放，并检查梯度是否含Inf/NaN；检测到非有限梯度时，可以跳过optimizer.step。scaler.update调整缩放因子。因此“到达窗口末”“调用scaler.step”和“实际调用优化器step”要分别记录；优化器完成调用本身也不保证每项权重必有非零变化。',
  '需要梯度裁剪时，在窗口最后一次backward之后显式调用scaler.unscale_(optimizer)，再裁剪，随后step、update；同一窗口不能混用多个缩放因子。这个片段省略了裁剪和循环外围设置。若末尾不足accum次，要重新处理分母与更新边界；原训练实验直接拒绝这种配置。有效token不等时，应把loss/accum换成完整目标所需的缩放。'),

  p('峰值是同一时刻仍存活的对象之和在整个区间内的最大值。前向增加供反向使用的保存量，反向逐步消耗它们并建立梯度，更新时读取梯度和历史状态、可能申请临时量。不同阶段的最高值不一定重合。')+
  formula('按存活时间计算容量','M峰值 = maxₜ [M状态(t)+M激活(t)+M临时(t)+M其他(t)]','每列按不重叠的存储用途计数；共享存储先去重，再在同一时刻相加。')+
  p('另设20GiB容量练习：假定五类状态已经完成首次初始化，窗口开始将梯度设为None，其他训练状态为14GiB；梯度建立后恢复16GiB。下面三个给定时刻的激活与临时区互不重叠，省略项取0，数值是题设，不是CUDA实测。')+
  table(['时刻','当时状态','当时激活','当时临时区','同一时刻合计'],[
   ['A：前向末段，未分配梯度','14GiB','4GiB','1GiB','19GiB'],
   ['B：反向过程中，梯度已分配','16GiB','2GiB','3GiB','21GiB'],
   ['C：参数更新','16GiB','0GiB','2GiB','18GiB']
  ])+
  p('已知最高为21GiB，超过20GiB。分别取各列最大值再相加得到16+4+3=23GiB，组合了未必同时出现的对象。真实最高点还可能位于三个快照之间；首次step延迟建立的Adam状态，也会让首次与后续窗口不同。',
  '实际测量先固定rank、设备、输入长度、微批、累积和精度，选定本地rank使用的CUDA设备；同步已有工作，再重置峰值计数，执行包含forward、backward与更新的完整窗口，结束后同步并读取峰值。下面保留的是核心采样节选，接入时需补上前置同步与正确设备选择。首次窗口与稳态窗口分别记录。')+
  codes(m[6])[0]+
  p('allocated与reserved各有自己的峰值，reserved已包含分配器中的allocated；二者不能相加，两个峰值可能发生在不同时刻，也不能直接相减当作碎片量。设备工具还可能观察到CUDA上下文、NCCL等分配器之外的用量。容量看所有rank中最高的一张卡，并将连续区间峰值、阶段时间线、步耗时及数值结果一起记录。本章未新增GPU/NCCL测量。'),

  heading(m[7],'subsection-8-1hcmeye')+
  p('激活重计算（activation checkpointing）在选定边界保留较少的前向中间量，反向需要某个结果时，从边界输入重新算出。参数和Adam历史仍然保留，变化的是供反向使用的保存量及其寿命。持久化checkpoint则把训练状态写到可恢复存储，用于进程退出后的续训，两者的对象与用途不同。',
  '独立CPU实验checkpoint_saved_tensors.py使用3个Linear(32,64)→GELU→Linear(64,32)块，输入为[16,32]、FP32，无dropout。普通与use_reentrant=False重计算两路复制相同参数和输入。saved_tensors_hooks记录前向结束时供反向使用的张量，按底层存储去重并排除参数。')+
  table(['本例观察点','普通路径','重计算路径'],[
   ['各块输入，[16,32]×4字节','3×2048B','3×2048B'],
   ['各块内部两份[16,64]中间量','3×2×4096B','不在此处逐项保留'],
   ['损失使用的最终[16,32]输出','2048B','2048B'],
   ['前向结束的非参数保存载荷','32768B','8192B']
  ])+
  figures(m[7]).join('')+
  p('这里共少保留24576字节，但反向重算还会临时产生中间量；观察点的保存量下降不等于整步峰值恰好下降同样字节数。每块前向入口在反向前都计1次，反向后普通仍为[1,1,1]，重计算为[2,2,2]。非重入实现可在所需结果重建后提前停止，入口次数不能换算成整块完整执行次数或两倍耗时。',
  '本次输出、全部参数梯度及输入梯度的最大误差均为0。网络没有随机操作，这一结果不覆盖任意dropout、状态更新或副作用；更换边界时应同时比较数值、逐rank峰值和完整窗口用时。最后的实战区保留源码与运行记录。')+
  link('flash-attention-io','比较减少注意力中间矩阵读写的另一条路径')+
  link('checkpoint-recovery','区分持久化训练状态与激活重计算'),

  p('内存方案可以按它改变的对象理解：减小微批或重计算主要改变激活；优化器状态分片改变各rank常驻的历史；参数分片改变各rank常驻的权重；卸载改变存放设备。先把这些对象与第七节的同时存活时间对应，再决定哪种方案能降低当前最高点。',
  '分片把一份状态拆给多个rank。沿用P=2³⁰、BF16权重和梯度、FP32主副本及两份矩的五缓冲题，设4个rank理想等分，无填充、无卸载。下表只数这些状态，未均分激活、通信或临时聚合。')+
  table(['四rank的简化策略','每rank状态计算','结果'],[
   ['DDP完整复制','2+2+4+4+4','16GiB'],
   ['只均分主副本与两份矩','2+2+(4+4+4)/4','7GiB'],
   ['五类状态都均分','(2+2+4+4+4)/4','4GiB']
  ])+
  p('参数分片后，某个计算组开始前通常还需通过all-gather从各rank收齐该组参数；计算结束后可按策略释放完整副本或重新分片。FSDP2的分组、释放与预取时机决定这些临时对象怎样重叠。静态状态从16GiB降为4GiB，只回答常驻项，不能把完整峰值也除以4。')+
  heading(m[8],'subsection-9-1sk5pf9')+
  p('再设独立缓冲寿命题：单rank常驻4GiB，已包含本地分片；计算A组另需1GiB完整缓冲，B组另需0.5GiB。两缓冲与常驻存储互不共享，暂不计激活和其他项。先算顺序执行，再算预取重叠。')+
  figures(m[8]).join('')+
  table(['阶段','先释放A再准备B','A仍存活时预取B'],[
   ['初始','4GiB','4GiB'],
   ['收齐A','4+1=5GiB','4+1=5GiB'],
   ['准备B','4+0.5=4.5GiB','4+1+0.5=5.5GiB'],
   ['完成并释放','回到4GiB','回到4GiB']
  ])+
  p('容量5.25GiB时，顺序最高5GiB，重叠最高5.5GiB。预取试图用计算遮住通信，却同时延长缓冲重叠，必须结合时间收益与容量测量。若只将B改为0.2GiB，重叠最高5.2GiB，题设内可容纳；真实实现仍需计入省略项。',
  '遇到容量不足，先定位峰值阶段：激活主导时比较减微批和重计算；首次Adam初始化主导时检查状态精度与分片；all-gather附近主导时检查分组、预取与释放。保持同一目标与负载，对照最高rank的峰值、步耗时和数值结果，才能判断收益。')+
  heading(m[8],'subsection-9-r44dc9',1)+
  p('量化用较少位数表示指定对象，不能直接套到整张内存账。仅权重量化还需计比例尺等元数据，若执行时压缩权重与展开的高精度权重同时保留，就要计两份存储。激活、KV、梯度、优化器状态各有自己的格式和寿命。',
  '微调是在已有模型上继续训练。QLoRA保留低比特的冻结基座，另外训练参数较少的适配模块，即额外加入的可学习变换。基座不为自身更新建立梯度和Adam历史，但仍参与前向和反向计算，相关激活与工作区继续存在；适配模块有自己的参数、梯度和优化器状态。先列可训练对象和展开路径，再计算每项字节。<a href="https://arxiv.org/abs/2305.14314" target="_blank" rel="noopener">QLoRA原论文 ↗</a>')+
  link('quantization-serving','用32个权重核对分组开销，再看实际算子')+
  link('checkpoint-recovery','了解A2.8的持久化与恢复边界'),

  p('下面用Python标准库复算两份已经声明的题设。第一份将五类状态的每参数字节[2,2,4,4,4]乘P=2³⁰；第二份对三个给定时刻[14+4+1,16+2+3,16+0+2]取最大值。程序没有创建模型或测量显存。')+
  codes(m[9])[0]+
  p('预期依次输出17179869184、16、21，对应状态总字节、状态GiB、快照最高GiB。将梯度的2改为4，状态变为19,327,352,832字节，即18GiB，原16GiB断言应失败。三个快照需按各时刻的梯度存活重新推导，不能机械给每行都加2。',
  '再独立改变第二份题设：只把B时刻激活由2GiB减到1GiB，其余保持，三行变为19、20、18GiB，最高20GiB。题设内恰好触线；下一步要在目标环境测连续区间，并补入此前省略的开销。静态算术确定了要验证的对象，实测确定实际容量。')+
  link('ddp-code','把更新边界带到A2.4训练程序'),

  heading(m[10],'subsection-11-em7gfe')+
  p('先运行tensor_state_bytes.py。run分别创建三份独立网络，inventory在创建、反向、step及清梯度后遍历参数、.grad与optimizer.state；payload用numel×element_size求和。读源码时按这三个名字找到“何时观察、观察什么、怎样计数”。')+
  codes(m[10])[0]+
  table(['先预测，再核对保留记录','结果'],[
   ['FP32参数；或FP32参数加BF16 autocast','232→464→944→712→944字节'],
   ['直接BF16参数','116→232→480→364→480字节'],
   ['首次step新建的键','exp_avg、exp_avg_sq、step'],
   ['两个view','逻辑48字节，共享底层32字节']
  ])+
  fold('展开完整tensor_state_bytes.py：与下载源码一致',codes(m[10])[1])+
  p('变化题：保持4个参数张量，将参数元素增加1000个。按FP32且首次step后仍保留梯度的同一策略，参数、梯度与两份矩各增加4000字节，合计增加16000字节；4个step标量仍为16字节。若参数张量数量也改变，计数标量需要另算。')+
  heading(m[10],'subsection-11-11crht8',1)+
  p('再运行checkpoint_saved_tensors.py。run中的pack记录shape、dtype、底层存储字节及是否属于参数，观察清单只存元数据；返回的detach张量供反向读取，避免额外挂住原Tensor的求导图。主程序复制相同网络后逐项对比输出与参数、输入梯度。')+
  codes(m[10])[2]+
  table(['观察项','保留CPU记录'],[
   ['前向结束的非参数保存存储','普通32768B，重计算8192B'],
   ['每块入口次数：反向前→后','普通[1,1,1]→[1,1,1]；重计算[1,1,1]→[2,2,2]'],
   ['输出最大误差 / 梯度最大误差','0 / 0']
  ])+
  fold('展开完整checkpoint_saved_tensors.py：与下载源码一致',codes(m[10])[3])+
  p('以上是已有PyTorch 2.5.1/CPU记录，本次未新增运行。第一例数保留的训练状态，第二例数指定观察点供反向保存的存储；两者都不报告CUDA峰值、reserved或CPU RSS。到GPU环境时，沿本章的完整窗口测量步骤，分别记录首次与稳态、每个rank的峰值、步耗时及相同目标下的数值结果。')
 ]);
})();


